// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        // fund the victim contract with the fuzzed amount
        vm.deal(address(c), amount);
        // the owner of c is the deployer, i.e. this test contract
        address owner = address(this);
        vm.deal(owner, 1 wei);
        uint256 ownerBefore = owner.balance;

        vm.prank(owner);
        c.sudicideAnyone();

        // General rule: self-destruction credits the CALLER with c's whole balance.
        assertTrue(owner.balance == ownerBefore + amount);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        // keep the caller's starting balance small so receiving c's balance cannot overflow
        vm.deal(actor, 0);
        vm.deal(address(c), amount);

        vm.prank(actor);
        try c.sudicideAnyone() {
            // Rule: after selfdestruct, the caller receives the contract's entire prior balance.
            assertTrue(actor.balance == amount);
        } catch {
            // sGuardPlus constructor makes test contract the owner; only it may call.
            // Owner path still must deliver balance to msg.sender (the owner).
        }
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function testNonOwnerCannotSelfDestruct(address caller) public {
        require(caller != address(0));
        bool reverted = false;
        bool succeeded;
        (succeeded) = true;
        try c.sudicideAnyone() { reverted = false; }
        catch { reverted = true; }
        assert(reverted);
    }
    receive() external payable {}
    fallback() external payable {}
}

